    "symptoms": {
      "heading": "Symptoms That May Need Surgical Evaluation",
      "intro": [
        "Some symptoms may indicate a condition requiring surgical assessment. Seek medical evaluation if you experience:"
      ],
      "items": [
        {
          "title": "Persistent or severe abdominal pain",
          "desc": "Ongoing, worsening or unexplained abdominal pain may require evaluation to identify the underlying cause."
        },
        {
          "title": "A new lump or swelling",
          "desc": "A lump in the abdomen, groin, breast, neck or other area should be assessed, particularly if it is painful, enlarging or persistent."
        },
        {
          "title": "Painful or enlarging hernia",
          "desc": "A swelling that becomes painful, firm or difficult to push back may require prompt medical assessment."
        },
        {
          "title": "Persistent vomiting or abdominal distension",
          "desc": "These symptoms, particularly when associated with severe abdominal pain or inability to pass stool or gas, may require urgent evaluation."
        },
        {
          "title": "Blood in the stool or rectal bleeding",
          "desc": "Persistent or unexplained bleeding should be medically evaluated to determine the underlying cause."
        },
        {
          "title": "Persistent anal pain or bleeding",
          "desc": "Pain, bleeding, swelling or discomfort around the anus may be associated with conditions such as piles, fissures or fistulas."
        },
        {
          "title": "Changes in bowel habits",
          "desc": "Persistent constipation, diarrhoea or a significant change in bowel habits may require medical assessment."
        },
        {
          "title": "Difficulty swallowing or a neck swelling",
          "desc": "Persistent swallowing difficulties or a new neck lump may require evaluation, including assessment of the thyroid or other structures."
        }
      ],
      "subsections": [],
      "important": "Severe or rapidly worsening abdominal pain, persistent vomiting, abdominal swelling with inability to pass stool or gas, heavy bleeding, sudden severe pain in a hernia or other rapidly worsening symptoms require urgent medical attention and may require Emergency Care."
    },
