      "heading": "Orthopaedics & Joint Replacement",
      "paras": [
        "Orthopaedics focuses on the diagnosis and treatment of conditions affecting the bones, joints, muscles, ligaments, tendons and supporting structures of the musculoskeletal system. At MIMS Hospital, the Orthopaedics & Joint Replacement speciality provides evaluation and treatment for injuries, degenerative joint conditions, fractures, sports-related problems and other musculoskeletal disorders.",
        "Treatment is planned according to the patient's condition, age, activity level and functional needs. Depending on the diagnosis, treatment may include medication, physiotherapy and rehabilitation, injections, minimally invasive procedures or surgery.",
        "The speciality also provides joint replacement services for patients with advanced joint damage or degeneration when conservative treatment no longer provides adequate relief or function."
      ]
