    "symptoms": {
      "heading": "Signs That May Need Prompt Medical Evaluation",
      "intro": [
        "Children may not always be able to clearly describe what they are experiencing. Parents and caregivers should seek medical evaluation if they notice:"
      ],
      "items": [
        {
          "title": "Persistent or high fever",
          "desc": "Especially when fever continues, keeps returning or is accompanied by other concerning symptoms."
        },
        {
          "title": "Difficulty breathing",
          "desc": "Rapid breathing, wheezing, breathlessness, chest retractions or visible difficulty breathing should be assessed promptly."
        },
        {
          "title": "Poor feeding or difficulty feeding",
          "desc": "Particularly in infants, persistent feeding difficulties may require medical evaluation."
        },
        {
          "title": "Persistent vomiting or diarrhoea",
          "desc": "Ongoing vomiting or diarrhoea can lead to dehydration and may require timely treatment."
        },
        {
          "title": "Unusual sleepiness or reduced responsiveness",
          "desc": "A child who is unusually drowsy, difficult to wake or less responsive than normal needs prompt medical attention."
        },
        {
          "title": "Poor weight gain or growth",
          "desc": "Falling behind expected growth patterns may require assessment of nutrition, development or underlying health conditions."
        },
        {
          "title": "Repeated or persistent infections",
          "desc": "Frequent or unusually prolonged infections may need further evaluation by a Paediatric specialist."
        },
        {
          "title": "Changes in behaviour or development",
          "desc": "Loss of previously acquired skills, developmental concerns or significant changes in behaviour should be discussed with a Paediatrician."
        },
        {
          "title": "Persistent abdominal pain",
          "desc": "Recurrent or severe abdominal pain, particularly when accompanied by vomiting, fever or other symptoms, should be evaluated."
        }
      ],
      "subsections": [],
      "important": "Severe difficulty breathing, seizures, loss of consciousness, severe dehydration, blue or grey lips or skin, sudden weakness, severe bleeding or a child who is difficult to wake requires urgent medical attention and may require Emergency Care."
    },
