    "symptoms": {
      "heading": "Symptoms That May Indicate a Hormonal Imbalance",
      "intro": [
        "Hormonal and metabolic disorders can develop gradually, and their symptoms may sometimes be mistaken for stress, ageing or other health concerns. Persistent or unexplained changes should be medically evaluated."
      ],
      "items": [
        {
          "title": "Persistent fatigue or low energy",
          "desc": "Ongoing tiredness may sometimes be associated with thyroid, adrenal, metabolic or other endocrine conditions."
        },
        {
          "title": "Unexplained weight gain or weight loss",
          "desc": "Significant changes in weight without clear changes in diet or activity may require evaluation."
        },
        {
          "title": "Persistent changes in blood sugar levels",
          "desc": "Frequently high or low blood glucose levels should be assessed and appropriately managed."
        },
        {
          "title": "Excessive thirst or frequent urination",
          "desc": "These may be associated with diabetes and other metabolic or hormonal conditions."
        },
        {
          "title": "Heat or cold intolerance",
          "desc": "Feeling unusually sensitive to heat or cold can sometimes be associated with thyroid disorders."
        },
        {
          "title": "Changes in heart rate or palpitations",
          "desc": "Persistent palpitations or unexplained changes in heart rate may require assessment for thyroid or other medical causes."
        },
        {
          "title": "Changes in hair or skin",
          "desc": "Persistent hair loss, unusual skin changes or excessive dryness may sometimes be associated with hormonal conditions."
        },
        {
          "title": "Irregular menstrual cycles or hormonal changes",
          "desc": "Persistent changes in menstrual patterns may require evaluation by an appropriate specialist."
        },
        {
          "title": "Unexplained muscle weakness",
          "desc": "Persistent weakness may occasionally be associated with electrolyte, adrenal or other endocrine disorders."
        },
        {
          "title": "Frequent fractures or loss of height",
          "desc": "These may indicate reduced bone strength or osteoporosis and should be evaluated."
        }
      ],
      "subsections": [],
      "important": "Severe weakness, confusion, loss of consciousness, severe dehydration, very high or very low blood sugar symptoms, or rapidly worsening health require urgent medical attention."
    },
