    "symptoms": {
      "heading": "Head & Neck Symptoms That Should Not Be Ignored",
      "intro": [
        "Many head and neck cancers can initially resemble common infections or other less serious conditions. Persistent or unexplained symptoms should be evaluated, particularly when they do not resolve with usual treatment."
      ],
      "items": [
        {
          "title": "A mouth or tongue ulcer that does not heal",
          "desc": "Persistent ulcers, particularly those lasting several weeks, should be examined by a healthcare professional."
        },
        {
          "title": "Unexplained lump or swelling in the neck",
          "desc": "A persistent neck lump may have several causes but should be medically evaluated."
        },
        {
          "title": "Difficulty swallowing",
          "desc": "Persistent or progressive difficulty swallowing may indicate a condition affecting the throat or oesophagus and requires assessment."
        },
        {
          "title": "Persistent hoarseness or voice changes",
          "desc": "Voice changes lasting for several weeks should be evaluated, particularly in the absence of an obvious infection."
        },
        {
          "title": "Unexplained bleeding from the mouth or nose",
          "desc": "Recurrent or unexplained bleeding may require specialist evaluation."
        },
        {
          "title": "Persistent sore throat",
          "desc": "A sore throat that does not resolve or is associated with other symptoms should be assessed."
        },
        {
          "title": "Difficulty opening the mouth or chewing",
          "desc": "Persistent restriction may be associated with conditions affecting the oral cavity, jaw or surrounding tissues."
        },
        {
          "title": "Unexplained facial or jaw swelling",
          "desc": "Persistent swelling of the face, jaw or oral tissues warrants evaluation."
        },
        {
          "title": "Persistent ear pain without an obvious ear problem",
          "desc": "Referred ear pain can occasionally originate from conditions affecting the throat or other head and neck structures."
        },
        {
          "title": "Unexplained weight loss",
          "desc": "Significant unintentional weight loss accompanying persistent head and neck symptoms should be medically assessed."
        }
      ],
      "subsections": [],
      "important": "Difficulty breathing, rapidly increasing swelling of the face or neck, uncontrolled bleeding or sudden inability to swallow requires urgent medical attention."
    },
