    "symptoms": {
      "heading": "Neurological & Spinal Symptoms That Need Medical Attention",
      "intro": [
        "Some symptoms may have several possible causes, while others can indicate a serious neurological or neurosurgical condition. Seek medical evaluation if you experience:"
      ],
      "items": [
        {
          "title": "Sudden severe headache",
          "desc": "A sudden, unusually intense headache, particularly when it develops abruptly, requires urgent assessment."
        },
        {
          "title": "Loss of consciousness or repeated fainting",
          "desc": "Unexplained loss of consciousness may require neurological evaluation."
        },
        {
          "title": "Progressive weakness or paralysis",
          "desc": "Increasing weakness in an arm, leg or other part of the body may indicate nerve, spinal cord or brain involvement."
        },
        {
          "title": "Numbness or loss of sensation",
          "desc": "Persistent or progressive numbness may occur with nerve or spinal cord compression and should be evaluated."
        },
        {
          "title": "Difficulty walking or maintaining balance",
          "desc": "New or worsening problems with coordination, walking or balance may require neurological assessment."
        },
        {
          "title": "Persistent or worsening back or neck pain",
          "desc": "Pain accompanied by weakness, numbness or changes in bladder or bowel function requires prompt evaluation."
        },
        {
          "title": "Changes in speech or vision",
          "desc": "Sudden difficulty speaking or unexplained visual changes can indicate an acute neurological problem."
        },
        {
          "title": "Seizures",
          "desc": "A first seizure or unexplained recurrent seizures require medical assessment."
        },
        {
          "title": "Persistent vomiting with severe headache",
          "desc": "Particularly when associated with visual, neurological or consciousness changes."
        },
        {
          "title": "Loss of bladder or bowel control",
          "desc": "New loss of bladder or bowel control, particularly with back pain or leg weakness, requires urgent assessment."
        }
      ],
      "subsections": [],
      "important": "Sudden weakness, facial drooping, difficulty speaking, loss of consciousness, seizures, sudden severe headache or rapidly worsening neurological symptoms require immediate Emergency Care."
    },
    "treatments": {
      "heading": "Advanced Neurosurgical Treatment & Intervention",
      "intro": [
        "Neurosurgical treatment is carefully planned based on the patient's diagnosis, symptoms, imaging findings, overall health and expected benefit from surgery. Depending on the condition, treatment may involve conventional surgery, minimally invasive techniques, microsurgery or other specialised approaches."
      ],
      "items": [
        {
          "title": "Brain Surgery",
          "desc": "Surgical procedures may be performed to remove or biopsy selected brain tumours, treat bleeding or address other structural conditions affecting the brain."
        },
        {
          "title": "Spine Surgery",
          "desc": "Surgical treatment for selected spinal conditions may include decompression, disc surgery, stabilisation or fusion where clinically indicated."
        },
        {
          "title": "Minimally Invasive Spine Surgery",
          "desc": "Selected spinal conditions may be treated using minimally invasive approaches designed to minimise tissue disruption and support recovery."
        },
        {
          "title": "Microsurgical Procedures",
          "desc": "Microsurgical techniques may be used for selected complex procedures where precision around delicate neurological structures is essential."
        },
        {
          "title": "Tumour Surgery",
          "desc": "Surgical removal or biopsy of selected brain and spinal tumours, often as part of a multidisciplinary treatment plan."
        },
        {
          "title": "Neurotrauma Surgery",
          "desc": "Emergency neurosurgical intervention may be required for serious traumatic brain injuries, intracranial bleeding or other forms of neurotrauma."
        },
        {
          "title": "Hydrocephalus Treatment",
          "desc": "Surgical procedures may be used to restore or divert cerebrospinal fluid flow in patients with hydrocephalus."
        },
        {
          "title": "Peripheral Nerve Surgery",
          "desc": "Selected compressed, injured or damaged nerves may be treated surgically to relieve compression or restore function where possible."
        },
        {
          "title": "Post-operative Neurosurgical Care",
          "desc": "Patients receive appropriate monitoring and follow-up after surgery, with rehabilitation and specialist support when required."
        }
      ],
      "subsections": [
        {
          "heading": "Comprehensive Procedures & Surgeries",
          "intro": [
            "Neurosurgery involves highly specialised procedures where precision and careful planning are essential. Depending on the diagnosis and clinical requirements, procedures may include:"
          ],
          "items": [
            {
              "title": "Craniotomy",
              "desc": "A surgical procedure involving temporary removal of a section of the skull to access the brain for selected tumour, vascular, traumatic or other neurosurgical conditions."
            },
            {
              "title": "Brain Tumour Resection",
              "desc": "Surgical removal of a brain tumour when appropriate, with the extent of surgery determined by the tumour's location, type and relationship to critical neurological structures."
            },
            {
              "title": "Spinal Decompression",
              "desc": "Removal of structures causing pressure on the spinal cord or nerves in selected patients with spinal stenosis, disc disease or other compressive conditions."
            },
            {
              "title": "Discectomy",
              "desc": "Removal of part of a damaged or herniated disc to relieve pressure on a spinal nerve or the spinal cord when surgery is indicated."
            },
            {
              "title": "Spinal Fusion & Stabilisation",
              "desc": "Surgical techniques used to stabilise selected segments of the spine when instability or structural problems require surgical treatment."
            },
            {
              "title": "Aneurysm & Vascular Surgery",
              "desc": "Selected cerebral aneurysms and vascular abnormalities may require specialised surgical or endovascular treatment depending on their characteristics."
            },
            {
              "title": "CSF Diversion Procedures",
              "desc": "Procedures such as shunt placement may be considered for selected patients with hydrocephalus or disorders of cerebrospinal fluid circulation."
            },
            {
              "title": "Peripheral Nerve Procedures",
              "desc": "Selected nerve compression or injury conditions may be treated through surgical decompression, repair or reconstruction."
            }
          ]
        }
      ]
    },
