    "faqs": [
      {
        "q": "When should I see a urologist?",
        "a": "You should consider a urological consultation for persistent urinary symptoms, blood in the urine, recurrent urinary infections, kidney or urinary stones, difficulty passing urine, prostate symptoms or male reproductive concerns."
      },
      {
        "q": "Does every kidney stone require surgery?",
        "a": "No. Management depends on factors such as the stone's size, location, symptoms and whether it is causing obstruction or other complications. Some stones can pass naturally or be managed medically, while others require a procedure."
      },
      {
        "q": "What causes blood in the urine?",
        "a": "Blood in the urine can have several causes, including urinary infections, stones, prostate conditions and other urinary tract disorders. It should be evaluated rather than ignored."
      },
      {
        "q": "Can urological conditions be treated without surgery?",
        "a": "Yes. Depending on the diagnosis, treatment may involve medication, lifestyle changes, observation or other non-surgical approaches. Surgery or a minimally invasive procedure is considered when clinically appropriate."
      },
      {
        "q": "Does a urologist treat male reproductive problems?",
        "a": "Yes. Urologists also diagnose and treat several conditions affecting the male reproductive system, including selected testicular, prostate and sexual health conditions."
      }
    ]
